    H_\mathrm{XXZ} &= \frac{1}{4} \sum_{n} \left( X_n X_{n+1} + Y_n Y_{n+1} + \Delta Z_n Z_{n+1} \right) - \frac{h}{2} \sum_{n} X_n\;,\label{eq:XXZ}
